Voici un exemple de programme C++ qui lit un fichier texte ligne par ligne et compte le nombre d'occurrences d'un mot spécifique dans le fichier :

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>

using namespace std;

int main() {
    string fileName; // nom du fichier à lire
    string searchTerm; // mot à chercher dans le fichier

    // Demander l'emplacement du fichier et le mot à chercher
    cout << "Entrez le nom du fichier à lire : ";
    cin >> fileName;

    cout << "Entrez le mot à chercher : ";
    cin >> searchTerm;

    // Ouvrir le fichier pour lecture
    ifstream inputFile(fileName);

    if (!inputFile) {
        cerr << "Erreur : Impossible d'ouvrir le fichier " << fileName << endl;
        return 1; // Retourner une erreur si le fichier ne peut pas être ouvert
    }

    // Initialiser le compteur de mots trouvés à zéro
    int wordCount = 0;

    // Boucle de lecture des lignes du fichier
    string line;
    while (getline(inputFile, line)) {

        // Convertir la ligne en petit lettres pour éviter les cas sensibles
        transform(line.begin(), line.end(), line.begin(), ::tolower);

        // Compter le nombre de mots de la ligne correspondant au terme de recherche
        size_t pos = 0;
        while ((pos = line.find(searchTerm, pos)) != string::npos) {
            wordCount++;
            pos += searchTerm.length();
        }
    }

    // Fermer le fichier
    inputFile.close();

    // Afficher le nombre de mots trouvés
    cout << "Le mot \"" << searchTerm << "\" a été trouvé " << wordCount << " fois dans le fichier " << fileName << endl;

    return 0;
}
```

L'implémentation du programme est la suivante :

1. Importez les bibliothèques nécessaires : `iostream`, `fstream`, `string`, et `algorithm`.
2. Déclarer les variables nécessaires pour stocker le nom du fichier à lire, le mot à chercher, ainsi que le compteur de mots trouvés.
